// Some portions generated by Claude
import cytoscape, { type Core, type LayoutOptions as CytoscapeLayoutOptions } from 'cytoscape';
import fcose from 'cytoscape-fcose';
import {separateLayoutRectangles} from './graph-layout-overlap.ts';
export {separateLayoutRectangles} from './graph-layout-overlap.ts';
import { graphNodeSize } from './graph-geometry.ts';
import { layoutTopology, layoutNodeFixed } from './graph-layout-topology.ts';
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';
import type { Graph, PointerPosition } from './graph-types.ts';
import type { LayoutOptions } from './graph-layout-engine.ts';

cytoscape.use(fcose);
const sizeOf = (node: Graph['nodes'][number], options: LayoutOptions) => options.nodeSizes?.get(node.id) ?? graphNodeSize(node);

/** fCoSE runs only inside our disposable layout worker, never in the renderer. */
export function computeNetworkLayout(graph: Graph, options: LayoutOptions = {}) {
  if (graph.nodes.length < 2 || graph.nodes.every(node => layoutNodeFixed(node, options))) {
    return {positions: new Map(graph.nodes.map(node => [node.id, {x: node.x ?? 0, y: node.y ?? 0}])), bends: new Map<string, number>()};
  }
  const fixed = graph.nodes.filter(node => layoutNodeFixed(node, options));
  const topology = layoutTopology(graph);
  const hub = topology.findNode(id => topology.degree(id) === graph.nodes.length - 1);
  if (graph.nodes.length >= 20 && hub !== undefined && !options.nodeSizes &&
      topology.everyNode(id => id === hub || topology.degree(id) === 1) && !options.incremental && !options.localNodeIds?.size &&
      fixed.every(node => node === graph.nodes[Number(hub)])) {
    const root = graph.nodes[Number(hub)], center = {x: root.x ?? 0, y: root.y ?? 0};
    const positions = new Map<string, PointerPosition>([[root.id, center]]);
    let slot = 0, spacing = 0;
    graph.nodes.forEach(node => {const size = graphNodeSize(node); spacing = Math.max(spacing, Math.hypot(size.width + gap.nodeGapX, size.height + gap.nodeGapY) + 14);});
    graph.nodes.forEach(node => {
      if (node === root) return;
      const angle = slot * Math.PI * (3 - Math.sqrt(5));
      const radius = Math.max(210, graphNodeSize(root).width / 2 + spacing * .8) + Math.max(90, spacing * .55) * Math.sqrt(slot++);
      positions.set(node.id, options.refine && node.x !== undefined && node.y !== undefined ? {x: node.x, y: node.y}
        : {x: center.x + Math.cos(angle) * radius, y: center.y + Math.sin(angle) * radius});
    });
    separateLayoutRectangles(graph, positions, options);
    return {positions, bends: new Map<string, number>()};
  }
  const index = new Map(graph.nodes.map((node, i) => [node.id, i]));
  const springs = (options.springs ?? []).filter(spring => index.has(spring.source) && index.has(spring.target) && spring.source !== spring.target);
  let seed = options.seed ?? 42;
  const random = Math.random;
  let cy: Core | undefined;
  // fCoSE has no RNG hook. This synchronous worker-local scope always restores
  // Math.random, including constructor and solver failures.
  Math.random = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 4294967296;
  };
  try {
    cy = cytoscape({headless: true, styleEnabled: true, layout: {name: 'preset'},
      style: [{selector: 'node', style: {width: 'data(width)', height: 'data(height)', 'border-width': 0, padding: '0px'}}],
      elements: [
        ...graph.nodes.map((node, i) => {
          const size = sizeOf(node, options), halo = options.halos?.get(node.id) ?? 0;
          return {data: {id: 'n' + i,
            width: Math.max(size.width + 24, halo), height: Math.max(size.height + 18, halo)}, position: {x: node.x ?? 0, y: node.y ?? 0}};
        }),
        ...topology.mapEdges((edge, _attributes, source, target) => ({data: {id: 'e' + edge, source: 'n' + source, target: 'n' + target, ideal: 70, el: .35}})),
        ...springs.map((spring, i) => ({data: {id: 's' + i, source: 'n' + index.get(spring.source), target: 'n' + index.get(spring.target), ideal: spring.ideal, el: spring.elasticity}})),
      ],
    });
    cy.layout({name: 'fcose', quality: 'proof', randomize: !options.incremental && !options.localNodeIds?.size && !options.refine,
      animate: false, fit: false, packComponents: false, nodeDimensionsIncludeLabels: false,
      uniformNodeDimensions: false, sampleSize: Math.min(50, graph.nodes.length), nodeSeparation: 100,
      nodeRepulsion: 6500, numIter: 2500,
      // Function-valued only when springs ask for their own lengths: fcose treats constants and functions alike per
      // edge, but the plain path stays byte-identical to the one every layout test was tuned on.
      idealEdgeLength: springs.length ? (edge: {data: (key: string) => number}) => edge.data('ideal') : 70,
      edgeElasticity: springs.length ? (edge: {data: (key: string) => number}) => edge.data('el') : .35,
      gravity: .2, gravityRange: 3.8, tile: true, tilingPaddingHorizontal: gap.nodeGapX, tilingPaddingVertical: gap.nodeGapY,
      fixedNodeConstraint: fixed.map(node => ({nodeId: 'n' + index.get(node.id), position: {x: node.x ?? 0, y: node.y ?? 0}})),
    } as unknown as CytoscapeLayoutOptions).run();
    const positions = new Map<string, PointerPosition>();
    graph.nodes.forEach((node, i) => {
      const p = cy!.getElementById('n' + i).position();
      if (!Number.isFinite(p.x) || !Number.isFinite(p.y)) throw new Error('Non-finite layout result.');
      positions.set(node.id, {x: p.x, y: p.y});
    });
    fixed.forEach(node => positions.set(node.id, {x: node.x ?? 0, y: node.y ?? 0}));
    separateLayoutRectangles(graph, positions, options);
    return {positions, bends: new Map<string, number>()};
  } finally {
    cy?.destroy();
    Math.random = random;
  }
}
